<script>
import {api,money,date} from '../api'
export default{data:()=>({items:[],busy:true,error:''}),async mounted(){await this.load()},methods:{money,date,async load(){this.busy=true;this.error='';try{this.items=await api('/recommendations?limit=20')}catch(e){this.error=e.message}finally{this.busy=false}}}}
</script>
<template><q-page class="container"><div class="eyebrow">HECHO PARA TI</div><h1 class="page-heading">Tu próxima experiencia</h1><p>Recomendaciones según tus intereses, ubicación y actividad disponible.</p><q-banner v-if="error" class="error" role="alert">{{error}}</q-banner><div v-if="busy" class="empty"><q-spinner/> Cargando recomendaciones…</div><div v-else-if="!items.length&&!error" class="empty">Aún no hay recomendaciones disponibles. <router-link to="/perfil">Configura tus intereses</router-link>.</div><div v-else class="event-grid"><router-link class="event-card" v-for="(item,index) in items" :key="item.eventId" :to="'/evento/'+item.eventId"><div class="event-cover" :class="'cover-'+index%4"><span>{{item.category}}</span><strong>✳</strong></div><div class="event-info"><small>{{date(item.startDate)}}</small><h3>{{item.name}}</h3><p>{{item.city}}</p><strong>{{money(item.price,item.currency)}}</strong><p class="reason">{{item.reason}}</p></div></router-link></div></q-page></template>
